pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        c.approve(alice, 1);
        vm.startPrank(alice);
        c.transferFrom(address(this), alice, 1);
        vm.stopPrank();
        bool ok;
        try c.burn(1) { ok = true; } catch { ok = false; }
        assertTrue(ok == true);
    }
}

